/** Les vues se répartissent selon « qui doit agir » : c'est la question que tout le monde se pose. */
type Onglet = "atraiter" | "autres" | "cloturees" | "livraisons" | "bloquees" | "chiffres";
type OngletNc = Exclude<Onglet, "livraisons" | "bloquees" | "chiffres">;

/** Le serveur filtre déjà ce que chacun a le droit de voir : l'écran ne doit jamais masquer davantage. */
const PORTEE_LIBRE: Portee = { siteFixe: null, zoneFixe: null };
const CAUSES = ["magasin", "garde", "showroom", "commercial", "client", "systeme", "autre"] as const;

type Acteur = "responsable" | "coordinateur";

const STATUT_LABEL: Record<NcStatut, string> = {
  ouverte: "À expliquer",
  contestee: "À expliquer",
  expliquee: "En attente de décision",
  action_en_cours: "Action corrective",
  cloturee: "Clôturée",
};

const STATUT_BADGE: Record<NcStatut, string> = {
  ouverte: "badge-danger",
  contestee: "badge-danger",
  expliquee: "badge-info",
  action_en_cours: "badge-progress",
  cloturee: "badge-success",
};

/** Qui doit agir maintenant ? (null = terminé) */
function acteurDe(n: NonConformite): Acteur | null {
  if (n.statut === "ouverte" || n.statut === "contestee" || n.statut === "action_en_cours") return "responsable";
  if (n.statut === "expliquee") return "coordinateur";
  return null;
}

const ACTEUR_LABEL: Record<Acteur, string> = { responsable: "Le responsable du magasin", coordinateur: "Le coordinateur" };

/** Phrase unique « prochaine étape » : qui fait quoi, et pour quand. */
function prochaineEtape(n: NonConformite): string {
  switch (n.statut) {
    case "ouverte":
    case "contestee":
      return `Le responsable du magasin doit expliquer — ${delaiTexte(n.limiteJustif)}`;
    case "expliquee":
      return "Le coordinateur doit trancher : accepter l'explication ou confirmer la non-conformité";
    case "action_en_cours":
      return `Le responsable doit réaliser l'action corrective — échéance ${n.actionEcheance ?? "?"}`;
    default:
      if (n.decision === "annulee") return "Annulée : le temps se compte désormais depuis l'entrée du client";
      return n.decision === "acceptee" ? "Explication acceptée" : n.action ? "Action corrective réalisée" : "Terminée";
  }
}

/**
 * Dans quelle vue range-t-on cette non-conformité pour CET utilisateur ?
 *  - atraiter : c'est à moi d'agir (le coordinateur y retrouve aussi les retards à relancer)
 *  - autres   : quelqu'un d'autre doit agir
 *  - cloturees: terminé
 */
function vueDe(n: NonConformite, role: string): OngletNc {
  const acteur = acteurDe(n);
  if (!acteur) return "cloturees";
  if (role === "responsable") return acteur === "responsable" ? "atraiter" : "autres";
  // coordinateur / admin : décide, et relance quand le responsable est en retard
  if (acteur === "coordinateur") return "atraiter";
  return n.enRetardJustif || n.enRetardAction ? "atraiter" : "autres";
}

function isoJour(d: Date) {
  return d.toISOString().slice(0, 10);
}

/** « reste 5 h » / « en retard de 3 h » à partir d'une date limite. */
function delaiTexte(limite: string | null): string {
  if (!limite) return "";
  const diffMin = Math.round((new Date(limite).getTime() - Date.now()) / 60000);
  const abs = Math.abs(diffMin);
  const txt = abs < 60 ? `${abs} min` : abs < 2880 ? `${Math.round(abs / 60)} h` : `${Math.round(abs / 1440)} j`;
  return diffMin >= 0 ? `reste ${txt}` : `en retard de ${txt}`;
}

function csvEscape(v: unknown): string {
  const s = String(v ?? "").replace(/"/g, '""');
  return /[";\n]/.test(s) ? `"${s}"` : s;
}

function exporterCsv(liste: NonConformite[]) {
  const entetes = [
    "Date", "Type", "Statut", "Commande", "Client", "Expédition", "Site", "Zone", "Responsable(s)", "Détail",
    "Motifs", "Explication", "Décision", "Commentaire contrôleur", "Action corrective", "Échéance", "Clôturée le",
  ];
  const lignes = liste.map((n) => [
    formatDateTime(n.creeLe), n.typeLabel, STATUT_LABEL[n.statut], n.numCmd, n.client, n.numExpedition, n.site, n.zone,
    n.responsableEmail, n.detail, n.motifs, n.explication, n.decision, n.controleurCommentaire, n.action,
    n.actionEcheance ?? "", n.clotureLe ? formatDateTime(n.clotureLe) : "",
  ]);
  const csv = "﻿" + [entetes, ...lignes].map((l) => l.map(csvEscape).join(";")).join("\r\n");
  const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" }));
  const a = document.createElement("a");
  a.href = url;
  a.download = `non-conformites_${isoJour(new Date())}.csv`;
  a.click();
  URL.revokeObjectURL(url);
}

export default function NonConformitesMagasinPage() {
  const { user } = useAuth();
  const email = user?.email ?? "";
  const estControleur = user?.role === "coordinateur" || user?.role === "admin"; // droit de décision
  const estCoordinateur = user?.role === "coordinateur";
  const autorise = estControleur || estCoordinateur || user?.role === "responsable";
  const role = user?.role ?? "";

  const [recherche, setRecherche] = useState("");
  const [type, setType] = useState("");
  const portee = PORTEE_LIBRE;
  const [site, setSite] = useState("");
  const [zone, setZone] = useState("");
  const [periode, setPeriode] = useState<Periode>(() => periodeDepuisPreset("90"));
  const [ouvert, setOuvert] = useState<string | null>(null);
  const [nouveau, setNouveau] = useState(false);

  const depuis = periode.debut || "2000-01-01";

  const q = useQuery({
    queryKey: ["non-conformites", email, depuis],
    queryFn: () => api.nonConformites.lister(email, depuis),
    enabled: !!email && autorise,
    refetchInterval: 60_000,
  });
  const toutes = useMemo(() => q.data?.liste ?? [], [q.data]);
  const types = q.data?.types ?? [];
  const qBloquees = useQuery({
    queryKey: ["bloquees", email],
    queryFn: () => api.nonConformites.bloquees(email),
    enabled: !!email && autorise && estControleur,
    refetchInterval: 120_000,
  });
  const nBloquees = qBloquees.data?.livraisons.length ?? 0;

  const filtrees = useMemo(
    () =>
      toutes.filter((n) => {
        if (type && n.type !== type) return false;
        if (site && n.site !== site) return false;
        if (zone && !memeMagasin(n.zone, zone)) return false;
        // La période ne concerne que l'historique : une non-conformité encore ouverte reste toujours visible
        if (n.statut === "cloturee" && !dansPeriode(n.creeLe, periode)) return false;
        if (recherche.trim()) {
          const r = recherche.trim();
          if (![n.numCmd, n.client, n.zone, n.detail, n.typeLabel, n.responsableEmail].some((c) => includesLower(c, r))) return false;
        }
        return true;
      }),
    [toutes, type, site, zone, periode, recherche],
  );

  const parOnglet = useMemo(() => {
    const o: Record<OngletNc, NonConformite[]> = { atraiter: [], autres: [], cloturees: [] };
    filtrees.forEach((n) => o[vueDe(n, role)].push(n));
    // Les plus urgentes d'abord : en retard, puis les plus anciennes
    const urgence = (n: NonConformite) => (n.enRetardJustif || n.enRetardAction ? 0 : 1);
    o.atraiter.sort((a, b) => urgence(a) - urgence(b) || (a.creeLe || "").localeCompare(b.creeLe || ""));
    return o;
  }, [filtrees, role]);

  const retards = useMemo(() => toutes.filter((n) => n.enRetardJustif).length, [toutes]);
  const actionsRetard = useMemo(() => toutes.filter((n) => n.enRetardAction).length, [toutes]);
  // Non-conformités encore ouvertes mais masquées par les filtres actifs (période, site, magasin…)
  const masquees = useMemo(
    () => toutes.filter((n) => n.statut !== "cloturee" && !filtrees.includes(n)).length,
    [toutes, filtrees],
  );
  const fiche = ouvert ? toutes.find((n) => n.id === ouvert) ?? null : null;
  const ncParExp = useMemo(() => {
    const m = new Map<string, NonConformite[]>();
    toutes.forEach((n) => { if (n.expId) m.set(n.expId, [...(m.get(n.expId) ?? []), n]); });
    return m;
  }, [toutes]);

  const onglets: (Vue & { key: Onglet })[] = [
    { key: "atraiter", label: "À traiter", n: parOnglet.atraiter.length, alerte: parOnglet.atraiter.some((x) => x.enRetardJustif || x.enRetardAction) },
    { key: "autres", label: "En attente des autres", n: parOnglet.autres.length },
    { key: "cloturees", label: "Clôturées", n: parOnglet.cloturees.length },
    ...(estControleur ? [{ key: "livraisons" as Onglet, label: "Livraisons (frise)" }, { key: "bloquees" as Onglet, label: "Bloquées", n: nBloquees, alerte: nBloquees > 0 }, { key: "chiffres" as Onglet, label: "Chiffres" }] : []),
  ];
  const [onglet, setOnglet] = useVues<Onglet>("/non-conformites", onglets, "atraiter");

  if (!autorise) {
    return (
      <div className="h-full flex items-center justify-center p-6">
        <div className="card p-8 text-center max-w-md">
          <h2 className="text-lg font-semibold text-slate-900 mb-2">Accès réservé</h2>
          <p className="text-sm text-slate-500">Cette page est réservée aux responsables et aux coordinateurs.</p>
        </div>
      </div>
    );
  }


  const liste = onglet === "chiffres" || onglet === "livraisons" || onglet === "bloquees" ? [] : parOnglet[onglet];

  return (
    <div className="h-full flex flex-col">
      <PageHeader
        title="Non-conformités"
        subtitle={
          <>
            {user?.nom}
            {user?.site && ` — ${user.site}`} · <strong className="text-slate-800">{parOnglet.atraiter.length} à traiter par vous</strong>
            {" · "}{parOnglet.autres.length} en attente des autres
            {retards > 0 && <span className="text-red-600 font-medium"> · {retards} explication(s) en retard</span>}
            {actionsRetard > 0 && <span className="text-red-600 font-medium"> · {actionsRetard} action(s) en retard</span>}
          </>
        }
        actions={
          <>
            {estControleur && (
              <button className="btn-primary gap-1.5" onClick={() => setNouveau(true)}>
                <Plus className="h-4 w-4" />
                <span className="hidden sm:inline">Nouveau constat</span>
              </button>
            )}
            {(estControleur || estCoordinateur) && (
              <button className="btn-outline gap-1.5" onClick={() => exporterCsv(filtrees)} disabled={!filtrees.length} title="Exporter la liste filtrée (Excel)">
                <Download className="h-4 w-4" />
                <span className="hidden sm:inline">Export</span>
              </button>
            )}
            <button className="btn-outline gap-1.5" onClick={() => q.refetch()} disabled={q.isFetching}>
              <RefreshCw className={cn("h-4 w-4", q.isFetching && "animate-spin")} />
              <span className="hidden sm:inline">Rafraîchir</span>
            </button>
          </>
        }
      >
        <div className="flex flex-wrap gap-2">
          <div className="relative flex-1 min-w-[180px]">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
            <input
              type="search"
              className="input pl-9"
              placeholder="Commande, client, zone, responsable…"
              value={recherche}
              onChange={(e) => setRecherche(e.target.value)}
            />
          </div>
          <select className="input w-auto" value={type} onChange={(e) => setType(e.target.value)} aria-label="Type">
            <option value="">Tous les types</option>
            {types.filter((t) => t.actif).map((t) => (
              <option key={t.code} value={t.code}>{t.label}</option>
            ))}
          </select>
          <SiteMagasinSelect portee={portee} site={site} zone={zone} onSite={setSite} onZone={setZone} />
          <PeriodeSelect value={periode} onChange={setPeriode} />
        </div>
        <div className="md:hidden flex gap-1 overflow-x-auto -mb-3 pb-0">
          {onglets.map((o) => (
            <button
              key={o.key}
              onClick={() => setOnglet(o.key)}
              className={cn(
                "shrink-0 px-3 py-2 text-sm font-medium border-b-2 transition-colors flex items-center gap-1.5",
                onglet === o.key ? "border-brand-900 text-brand-900" : "border-transparent text-slate-500 hover:text-slate-800",
              )}
            >
              {o.key === "chiffres" && <BarChart3 className="h-4 w-4" />}
              {o.key === "livraisons" && <GanttChartSquare className="h-4 w-4" />}
              {o.key === "bloquees" && <AlertTriangle className="h-4 w-4" />}
              {o.label}
              {o.n !== undefined && (
                <span className={cn("num text-xs rounded-full px-1.5 py-0.5", o.alerte ? "bg-red-100 text-red-700" : "bg-slate-100 text-slate-600")}>
                  {o.n}
                </span>
              )}
            </button>
          ))}
        </div>
      </PageHeader>

      <div className="flex-1 overflow-y-auto p-4 sm:p-6">
        {onglet !== "chiffres" && onglet !== "livraisons" && onglet !== "bloquees" && <GuideParcours />}
        {onglet !== "livraisons" && onglet !== "bloquees" && masquees > 0 && (
          <div className="mb-3 rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-xs text-amber-900">
            {masquees} non-conformité(s) encore ouverte(s) sont masquées par vos filtres (recherche, type, site ou magasin).
          </div>
        )}
        {onglet !== "livraisons" && onglet !== "bloquees" && q.isLoading ? (
          <div className="card p-6 text-center text-sm text-slate-500">Chargement…</div>
        ) : onglet !== "livraisons" && onglet !== "bloquees" && q.error ? (
          <div className="card p-6 border-red-200 bg-red-50 text-sm text-red-700">
            {q.error instanceof Error ? q.error.message : "Erreur"}
          </div>
        ) : onglet === "livraisons" ? (
          <Livraisons
            email={email}
            depuis={depuis}
            recherche={recherche}
            site={site}
            zone={zone}
            periode={periode}
            ncParExp={ncParExp}
            onOuvrirNc={(id) => setOuvert(id)}
          />
        ) : onglet === "bloquees" ? (
          <LivraisonsBloquees email={email} />
        ) : onglet === "chiffres" ? (
          <Suivi liste={filtrees} periode={periode} />
        ) : liste.length === 0 ? (
          <div className="card p-10 text-center text-sm text-slate-500">
            <CheckCircle2 className="h-8 w-8 mx-auto mb-2 text-emerald-500" />
            {onglet === "atraiter" && "Rien à traiter pour vous. Tout est à jour."}
            {onglet === "autres" && "Personne d'autre n'a de non-conformité à traiter."}
            {onglet === "cloturees" && "Aucune non-conformité clôturée sur la période."}
          </div>
        ) : (
          <div className="space-y-2">
            {liste.map((n) => (
              <Ligne key={n.id} n={n} onClick={() => setOuvert(n.id)} relance={onglet === "atraiter" && estControleur && acteurDe(n) === "responsable"} />
            ))}
          </div>
        )}
      </div>

      {fiche && <Fiche n={fiche} estControleur={estControleur} onClose={() => setOuvert(null)} />}
      {nouveau && <NouveauConstat onClose={() => setNouveau(false)} />}
    </div>
  );
}

// ─── Guide du parcours ───────────────────────────────────────────────────────

const ETAPES: { n: number; titre: string; acteur: string; texte: string }[] = [
  { n: 1, titre: "Anomalie repérée", acteur: "Automatique ou coordinateur", texte: "Retard, plaque différente, sortie sans photos, attente anormale… ou constat fait sur le terrain. Le responsable est prévenu." },
  { n: 2, titre: "Explication", acteur: "Responsable du magasin", texte: "Il explique ce qui s'est passé, sous 24 h." },
  { n: 3, titre: "Validation", acteur: "Coordinateur", texte: "Il regarde la frise, peut ajouter ses précisions ou corriger la cause. Puis il accepte l'explication (terminé) ou confirme la non-conformité : une action corrective avec échéance est demandée." },
  { n: 4, titre: "Action corrective", acteur: "Responsable du magasin", texte: "Il réalise l'action avant l'échéance et le dit ici : c'est clôturé." },
];

/** Le parcours en 4 étapes, avec l'acteur de chacune. Replié après la première lecture. */
function GuideParcours() {
  const CLE = "dmc.nc.guide.ferme";
  const [ouvert, setOuvert] = useState(() => {
    // Replié par défaut sur téléphone (il prendrait tout l'écran) ; ouvert sur ordinateur tant qu'on ne l'a pas fermé
    const grand = typeof window !== "undefined" && window.matchMedia?.("(min-width: 768px)").matches;
    try { const v = localStorage.getItem(CLE); return v === null ? !!grand : v !== "1"; } catch { return !!grand; }
  });
  const basculer = () => {
    setOuvert((v) => {
      try { localStorage.setItem(CLE, v ? "1" : "0"); } catch { /* stockage indisponible */ }
      return !v;
    });
  };
  return (
    <div className="mb-4 rounded-card border border-line bg-white">
      <button type="button" onClick={basculer} className="flex w-full items-center justify-between px-4 py-2.5 text-left" aria-expanded={ouvert}>
        <span className="text-sm font-medium text-slate-800">Comment ça marche ? <span className="font-normal text-slate-500">4 étapes, un seul acteur à chaque étape</span></span>
        <ChevronDown className={cn("h-4 w-4 text-slate-400 transition-transform", ouvert && "rotate-180")} />
      </button>
      {ouvert && (
        <ol className="grid gap-px border-t border-line bg-line sm:grid-cols-2 lg:grid-cols-4 overflow-hidden rounded-b-card">
          {ETAPES.map((e) => (
            <li key={e.n} className="bg-white p-3">
              <div className="flex items-center gap-2">
                <span className="flex h-5 w-5 items-center justify-center rounded-full bg-brand-900 text-[11px] font-semibold text-white">{e.n}</span>
                <span className="text-sm font-semibold text-slate-900">{e.titre}</span>
              </div>
              <div className="mt-1 text-[11px] font-medium uppercase tracking-wide text-brand-700">{e.acteur}</div>
              <p className="mt-0.5 text-xs text-slate-600">{e.texte}</p>
            </li>
          ))}
        </ol>
      )}
    </div>
  );
}

// ─── Ligne de liste ──────────────────────────────────────────────────────────

function Ligne({ n, onClick, relance }: { n: NonConformite; onClick: () => void; relance?: boolean }) {
  const alerte = n.enRetardJustif || n.enRetardAction;
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn("w-full text-left card card-hover p-4 animate-in", alerte && "border-red-300")}
    >
      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2 flex-wrap">
            <Flag className={cn("h-4 w-4 shrink-0", alerte ? "text-red-500" : "text-amber-500")} />
            <span className="font-semibold text-sm text-slate-900">{n.typeLabel}</span>
            {n.origine === "manuel" && <span className="badge-neutral">Constat terrain</span>}
            {relance && <span className="badge-warn">À relancer</span>}
          </div>
          <div className="mt-1 text-sm text-slate-700 flex items-center gap-2 flex-wrap">
            {n.numCmd && <span className="font-mono font-medium">{n.numCmd}</span>}
            {n.client && <><span className="text-slate-300">·</span><span className="truncate">{n.client}</span></>}
          </div>
          <div className="mt-0.5 text-xs text-slate-500 flex items-center gap-3 flex-wrap">
            {n.zone && <span>{n.zone}</span>}
            <span>{formatRelative(n.creeLe)}</span>
          </div>
          {n.detail && <p className="mt-1.5 text-xs text-slate-600 line-clamp-2">{n.detail}</p>}
          {n.statut !== "cloturee" && (
            <p className={cn("mt-1.5 text-xs flex items-center gap-1.5", alerte ? "text-red-700 font-medium" : "text-slate-700")}>
              <ArrowRight className="h-3.5 w-3.5 shrink-0" />
              {prochaineEtape(n)}
            </p>
          )}
        </div>
        <span className={cn(STATUT_BADGE[n.statut], "shrink-0")}>{STATUT_LABEL[n.statut]}</span>
      </div>
    </button>
  );
}

// ─── Fiche détaillée + actions ───────────────────────────────────────────────

function Fiche({ n, estControleur, onClose }: { n: NonConformite; estControleur: boolean; onClose: () => void }) {
  const { user } = useAuth();
  const toast = useToast();
  const qc = useQueryClient();
  const email = user?.email ?? "";
  const peutExpliquer = (user?.role === "responsable" || user?.role === "coordinateur" || user?.role === "admin") && (n.statut === "ouverte" || n.statut === "contestee");
  const peutDecider = estControleur && n.statut === "expliquee";
  const peutTerminer = n.statut === "action_en_cours" && (user?.role === "responsable" || user?.role === "coordinateur" || user?.role === "admin");

  // Champs (tous les hooks avant tout retour conditionnel)
  const [explication, setExplication] = useState("");
  const [motifs, setMotifs] = useState<Set<string>>(new Set());
  const [decision, setDecision] = useState<NcDecision | "">("");
  const [commentaire, setCommentaire] = useState("");
  const [action, setAction] = useState("");
  const [echeance, setEcheance] = useState(isoJour(new Date(Date.now() + 7 * 86400000)));
  const [fait, setFait] = useState("");
  // Cause réelle du retard : par défaut le magasin ; le coordinateur la corrige après avoir regardé la frise
  const [imputation, setImputation] = useState<string>(n.imputation || "magasin");
  const [precision, setPrecision] = useState("");
  const precisions = n.historique.filter((h) => h.texte.startsWith("Précision du coordinateur"));
  const peutPreciser = estControleur && n.statut !== "cloturee";
  const horsMagasin = imputation !== "magasin";
  const avecCause = n.type === "RETARD" || n.type === "ATTENTE";
  const peutVoirFrise = !!n.expId && (user?.role === "responsable" || estControleur);

  const { data: frise } = useQuery({
    queryKey: ["frise", n.expId, email],
    queryFn: () => api.nonConformites.frise(email, n.expId as string),
    enabled: peutVoirFrise,
    refetchInterval: 60_000,
    retry: false,
  });

  const { data: motifsRef = [] } = useQuery({
    queryKey: ["motifs-retard"],
    queryFn: () => api.referentiels.motifs(),
    enabled: peutExpliquer && n.type === "RETARD",
  });
  const { data: photos = [] } = useQuery({
    queryKey: ["nc-photos", n.id],
    queryFn: () => api.medias.list("NC-" + n.id),
    enabled: n.type === "CONSTAT",
  });

  const fin = (msg: string) => {
    toast.success(msg);
    qc.invalidateQueries({ queryKey: ["non-conformites"] });
    qc.invalidateQueries({ queryKey: ["expeditions"] });
    onClose();
  };
  const echec = (e: unknown) => toast.error(e instanceof Error ? e.message : "Erreur");

  const mExpliquer = useMutation({
    mutationFn: () =>
      api.nonConformites.justifier({
        id: n.id, acteurEmail: email, explication: explication.trim(), motifs: Array.from(motifs),
        imputation: avecCause ? imputation : undefined,
      }),
    onSuccess: () => fin(estControleur ? "Explication enregistrée — à valider dans « Votre décision »" : "Explication envoyée au coordinateur"),
    onError: echec,
  });
  const mPreciser = useMutation({
    mutationFn: () =>
      api.nonConformites.preciser({
        id: n.id, acteurEmail: email, texte: precision.trim(),
        imputation: avecCause && imputation !== (n.imputation || "magasin") ? imputation : undefined,
      }),
    onSuccess: () => {
      toast.success("Précision enregistrée — le responsable est prévenu");
      setPrecision("");
      qc.invalidateQueries({ queryKey: ["non-conformites"] });
    },
    onError: echec,
  });
  const mDecider = useMutation({
    mutationFn: () =>
      api.nonConformites.decider({
        id: n.id, acteurEmail: email, decision: decision as NcDecision, commentaire: commentaire.trim(),
        action: action.trim(), echeance,
        imputation: avecCause ? imputation : undefined,
      }),
    onSuccess: () =>
      fin(decision === "acceptee" ? "Explication acceptée — clôturée" : "Non-conformité confirmée — l'action corrective est demandée"),
    onError: echec,
  });
  const mTerminer = useMutation({
    mutationFn: () => api.nonConformites.terminerAction({ id: n.id, acteurEmail: email, commentaire: fait.trim() }),
    onSuccess: () => fin("Action corrective enregistrée — clôturée"),
    onError: echec,
  });

  function envoyerExplication(e: FormEvent) {
    e.preventDefault();
    if (n.type === "RETARD" && motifs.size === 0 && !horsMagasin) return toast.error("Choisis au moins un motif.");
    if (explication.trim().length < 5) return toast.error("Explique brièvement ce qui s'est passé.");
    mExpliquer.mutate();
  }
  function envoyerDecision(e: FormEvent) {
    e.preventDefault();
    if (!decision) return toast.error("Choisis une décision.");
    if (decision === "confirmee" && !commentaire.trim()) return toast.error("Explique pourquoi tu confirmes.");
    if (decision === "confirmee" && (!action.trim() || !echeance)) return toast.error("Précise l'action corrective et l'échéance.");
    mDecider.mutate();
  }

  return (
    <Modal open onClose={onClose} title={n.typeLabel} description={`${n.numCmd || "Sans commande"}${n.client ? " · " + n.client : ""}`} size="lg">
      <div className="space-y-4">
        <div className="flex items-center gap-2 flex-wrap">
          <span className={STATUT_BADGE[n.statut]}>{STATUT_LABEL[n.statut]}</span>
          {n.enRetardJustif && <span className="badge-danger">Sans explication depuis plus de 24 h</span>}
          {n.enRetardAction && <span className="badge-danger">Échéance dépassée</span>}
        </div>

        {/* Prochaine étape : toujours en haut, avec l'acteur */}
        {n.statut !== "cloturee" ? (
          <div className={cn("rounded-lg border p-3 text-sm flex gap-2", (peutExpliquer || peutDecider || peutTerminer) ? "border-brand-300 bg-brand-50 text-brand-900" : "border-line bg-slate-50 text-slate-700")}>
            <ArrowRight className="h-4 w-4 mt-0.5 shrink-0" />
            <div>
              <div className="font-semibold">
                {(peutExpliquer || peutDecider || peutTerminer) ? "C'est à vous d'agir" : `En attente : ${ACTEUR_LABEL[acteurDe(n) ?? "responsable"].toLowerCase()}`}
              </div>
              <div>{prochaineEtape(n)}</div>
              {!(peutExpliquer || peutDecider || peutTerminer) && (n.enRetardJustif || n.enRetardAction) && (
                <div className="mt-1 text-xs font-medium text-red-700">En retard : pensez à relancer le responsable.</div>
              )}
            </div>
          </div>
        ) : (
          <div className="rounded-lg border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-900 flex gap-2">
            <CheckCircle2 className="h-4 w-4 mt-0.5 shrink-0" />
            <div><span className="font-semibold">Terminée</span> — {prochaineEtape(n).toLowerCase()}{n.clotureLe ? `, le ${formatDateTime(n.clotureLe)}` : ""}</div>
          </div>
        )}

        <dl className="grid grid-cols-2 gap-x-4 gap-y-2 text-sm">
          <Info label="Ouverte" valeur={formatDateTime(n.creeLe)} />
          <Info label="Magasin" valeur={[n.zone, n.site].filter(Boolean).join(" — ") || "—"} />
          <Info label="Responsable(s)" valeur={n.responsableEmail || "À désigner"} />
          <Info label="Expédition" valeur={n.numExpedition || "—"} />
        </dl>

        {n.detail && (
          <div className="rounded-lg bg-amber-50 border border-amber-200 p-3 text-sm text-amber-900 flex gap-2">
            <AlertTriangle className="h-4 w-4 mt-0.5 shrink-0" />
            <span>{n.detail}</span>
          </div>
        )}

        {peutVoirFrise && frise && (
          <section className="rounded-lg border border-line p-3 space-y-2">
            <h3 className="text-sm font-semibold text-slate-900 flex items-center gap-1.5">
              <GanttChartSquare className="h-4 w-4 text-slate-500" />Où est passé le temps ?
            </h3>
            <FriseLivraison
              f={frise}
              onImputer={(peutExpliquer || peutDecider) && avecCause ? setImputation : undefined}
              imputationActive={imputation}
            />
            <Journal f={frise} />
          </section>
        )}

        {n.imputation && (
          <div className="rounded-lg bg-sky-50 border border-sky-200 p-3 text-sm text-sky-900">
            <span className="text-xs font-medium block">Cause identifiée</span>
            {n.imputationLabel}
            {n.imputeANom && <span className="block font-medium">Responsabilité portée par : {n.imputeANom}</span>}
            <span className="block text-xs text-sky-700">{n.imputeANom ? "Cette faute est comptée dans la notation de cette personne." : "Ce retard n'est pas imputé au magasin."}</span>
          </div>
        )}

        {photos.length > 0 && (
          <div className="flex gap-2 flex-wrap">
            {photos.map((p) => (
              <a key={p.id} href={p.dataUrl} target="_blank" rel="noreferrer">
                <img src={p.dataUrl} alt="Constat" className="h-24 w-24 object-cover rounded-lg border border-line" />
              </a>
            ))}
          </div>
        )}

        {(n.statut === "action_en_cours" || (n.statut === "cloturee" && n.action)) && (
          <div className="rounded-lg bg-indigo-50 border border-indigo-200 p-3 text-sm text-indigo-900">
            <div className="text-xs font-medium mb-0.5 flex items-center gap-1"><Wrench className="h-3.5 w-3.5" />Action corrective</div>
            {n.action} <span className="text-indigo-700">· échéance {n.actionEcheance}</span>
            {n.controleurCommentaire && <div className="mt-1 text-xs italic">Coordinateur : « {n.controleurCommentaire} »</div>}
          </div>
        )}
        {/* Deux niveaux : 1) le responsable explique, 2) le coordinateur précise puis valide */}
        {n.explication && n.statut !== "ouverte" && (
          <div className="rounded-lg bg-slate-50 border border-line p-3 text-sm">
            <div className="text-xs text-slate-500 mb-0.5">
              Niveau 1 — {n.expliquePar && n.expliquePar === n.responsableEmail ? "Explication du responsable" : `Explication de ${n.expliquePar || "le responsable"}`}
              {n.expliqueLe ? ` · ${formatDateTime(n.expliqueLe)}` : ""}
            </div>
            {n.motifs && <div className="font-medium text-slate-900">{n.motifs}</div>}
            <div className="text-slate-700">{n.explication}</div>
          </div>
        )}
        {(precisions.length > 0 || (n.controleurCommentaire && n.decision)) && (
          <div className="rounded-lg bg-sky-50 border border-sky-200 p-3 text-sm space-y-1.5">
            <div className="text-xs font-medium text-sky-800">Niveau 2 — Coordinateur</div>
            {precisions.map((h, i) => (
              <div key={i} className="text-sky-950">
                <span className="num text-xs text-sky-700 mr-1.5">{formatDateTime(h.at)}</span>
                <span className="font-medium">{h.par}</span> — {h.texte.replace(/^Précision du coordinateur( \(cause : [^)]*\))? : /, "")}
              </div>
            ))}
            {n.controleurCommentaire && n.decision && (
              <div className="text-sky-950">
                <span className="font-medium">{n.decision === "acceptee" ? "Explication acceptée" : "Non-conformité confirmée"}</span> — {n.controleurCommentaire}
              </div>
            )}
          </div>
        )}

        {peutExpliquer && (
          <form onSubmit={envoyerExplication} className="space-y-3 border-t border-line pt-4">
            <h3 className="text-sm font-semibold text-slate-900">{estControleur ? "Votre enquête" : "Ton explication"}</h3>
            {estControleur && (
              <p className="text-xs text-slate-500 -mt-1">
                Regardez la frise ci-dessus : si le retard ne vient pas du magasin, indiquez la vraie cause. Vous pouvez saisir le justificatif à la place du responsable, puis le valider par une décision.
              </p>
            )}
            {avecCause && <SelecteurCause valeur={imputation} onChange={setImputation} titre={estControleur ? "À qui est dû le retard ?" : "Le retard vient-il de quelqu'un d'autre ?"} />}
            {n.type === "RETARD" && !horsMagasin && (
              <div className="flex flex-wrap gap-1.5">
                {motifsRef.map((mot) => {
                  const sel = motifs.has(mot.libelle);
                  return (
                    <button
                      key={mot.id}
                      type="button"
                      onClick={() => setMotifs((p) => { const s = new Set(p); if (s.has(mot.libelle)) s.delete(mot.libelle); else s.add(mot.libelle); return s; })}
                      className={cn(
                        "px-2.5 py-1.5 rounded-full text-xs font-medium border transition-colors",
                        sel ? "bg-brand-900 text-white border-brand-900" : "bg-white text-slate-700 border-slate-200 hover:border-slate-300",
                      )}
                    >
                      {mot.libelle}
                    </button>
                  );
                })}
              </div>
            )}
            <textarea className="input min-h-[90px]" placeholder={horsMagasin ? "Que s'est-il passé ? Décrivez ce qui a retardé la livraison." : "Que s'est-il passé ? Qu'est-ce qui sera fait pour que cela ne se reproduise pas ?"} value={explication} onChange={(e) => setExplication(e.target.value)} />
            <button className="btn-primary w-full" disabled={mExpliquer.isPending}>
              {mExpliquer.isPending ? "Envoi…" : estControleur ? "Enregistrer l'explication" : "Envoyer au coordinateur"}
            </button>
          </form>
        )}

        {peutPreciser && (
          <div className="space-y-2 border-t border-line pt-4">
            <h3 className="text-sm font-semibold text-slate-900">Ajouter une précision <span className="font-normal text-slate-500">(sans trancher)</span></h3>
            <p className="text-xs text-slate-500 -mt-1">
              Complétez ou nuancez l'explication après avoir regardé la frise. Le responsable est prévenu{avecCause ? ' ; vous pouvez aussi corriger la cause' : ""}.
            </p>
            {avecCause && !peutExpliquer && !peutDecider && <SelecteurCause valeur={imputation} onChange={setImputation} titre="Cause réelle du retard" />}
            <textarea className="input min-h-[70px]" placeholder="Ex : le camion est resté 20 min devant le portail, le magasin n'y est pour rien" value={precision} onChange={(e) => setPrecision(e.target.value)} />
            <button type="button" className="btn-outline w-full" disabled={mPreciser.isPending || precision.trim().length < 5} onClick={() => mPreciser.mutate()}>
              {mPreciser.isPending ? "Enregistrement…" : "Enregistrer la précision"}
            </button>
          </div>
        )}

        {peutDecider && (
          <form onSubmit={envoyerDecision} className="space-y-3 border-t border-line pt-4">
            <h3 className="text-sm font-semibold text-slate-900">Votre décision</h3>
            {avecCause && <SelecteurCause valeur={imputation} onChange={setImputation} titre="Cause réelle du retard (après enquête)" />}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
              <ChoixDecision actif={decision === "acceptee"} onClick={() => setDecision("acceptee")} icone={<CheckCircle2 className="h-4 w-4" />} titre="Accepter l'explication" sous="C'est recevable : la non-conformité est clôturée" couleur="emerald" />
              <ChoixDecision actif={decision === "confirmee"} onClick={() => setDecision("confirmee")} icone={<Wrench className="h-4 w-4" />} titre="Confirmer la non-conformité" sous="C'est avéré : on demande une action corrective" couleur="red" />
            </div>
            {decision && (
              <textarea
                className="input min-h-[70px]"
                placeholder={decision === "acceptee" ? "Commentaire (facultatif)" : "Pourquoi confirmez-vous ? (obligatoire)"}
                value={commentaire}
                onChange={(e) => setCommentaire(e.target.value)}
              />
            )}
            {decision === "confirmee" && (
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
                <div className="sm:col-span-2">
                  <label className="label">Action corrective *</label>
                  <input className="input" placeholder="Ex : former l'équipe, ajouter un chariot…" value={action} onChange={(e) => setAction(e.target.value)} />
                </div>
                <div>
                  <label className="label">Échéance *</label>
                  <input type="date" className="input" value={echeance} min={isoJour(new Date())} onChange={(e) => setEcheance(e.target.value)} />
                </div>
              </div>
            )}
            <button className="btn-primary w-full" disabled={mDecider.isPending || !decision}>
              {mDecider.isPending ? "Enregistrement…" : "Valider ma décision"}
            </button>
          </form>
        )}

        {peutTerminer && (
          <div className="space-y-3 border-t border-line pt-4">
            <h3 className="text-sm font-semibold text-slate-900">Action réalisée ?</h3>
            <textarea className="input min-h-[70px]" placeholder="Décris ce qui a été fait" value={fait} onChange={(e) => setFait(e.target.value)} />
            <button className="btn-primary w-full" disabled={mTerminer.isPending || !fait.trim()} onClick={() => mTerminer.mutate()}>
              {mTerminer.isPending ? "Enregistrement…" : "Marquer l'action comme réalisée"}
            </button>
          </div>
        )}

        {n.historique.length > 0 && (
          <div className="border-t border-line pt-4">
            <h3 className="text-sm font-semibold text-slate-900 mb-2">Historique</h3>
            <ol className="space-y-2">
              {n.historique.map((h, i) => (
                <li key={i} className="text-xs text-slate-600 flex gap-2">
                  <span className="num text-slate-400 shrink-0 w-32 whitespace-nowrap">{formatDateTime(h.at)}</span>
                  <span><span className="font-medium text-slate-800">{h.par}</span> — {h.texte}</span>
                </li>
              ))}
            </ol>
          </div>
        )}
      </div>
    </Modal>
  );
}

/** « À qui est dû le retard ? » — le magasin par défaut, ou un autre acteur de la chaîne. */
function SelecteurCause({ valeur, onChange, titre }: { valeur: string; onChange: (v: string) => void; titre: string }) {
  return (
    <div>
      <div className="label">{titre}</div>
      <div className="flex flex-wrap gap-1.5">
        {CAUSES.map((c) => (
          <button
            key={c}
            type="button"
            onClick={() => onChange(c)}
            className={cn(
              "px-2.5 py-1.5 rounded-full text-xs font-medium border transition-colors",
              valeur === c ? (c === "magasin" ? "bg-brand-900 text-white border-brand-900" : "bg-sky-700 text-white border-sky-700") : "bg-white text-slate-700 border-slate-200 hover:border-slate-300",
            )}
          >
            {IMPUTATION_COURT[c]}
          </button>
        ))}
      </div>
    </div>
  );
}

const JALON_LABEL: Record<string, string> = {
  T0: "Commande inscrite", ENTREE_SITE: "Entrée sur le site", ENTREE_SHOWROOM: "Entrée showroom",
  ENTREE_TRANSFEREE: "Entrée déplacée", ENTREE_CORRIGEE: "Entrée corrigée", SAISIE_CODE: "Arrivée validée au magasin",
  PHOTOS_CHARGEMENT: "Photos du chargement", SORTIE_SITE: "Sortie du site", SORTIE_SHOWROOM: "Sortie showroom",
  PLAQUE_DIFFERENTE: "Plaque différente", ALERTE_VALIDATION_RAPIDE: "Validation très rapide", DEROGATION_PHOTOS: "Dérogation photos",
  ETAPE_ANNULEE: "Étape annulée", NC_OUVERTE: "Non-conformité ouverte", JUSTIF: "Justification", CTRL_OK: "Justificatif validé",
  CTRL_NOK: "Justificatif contredit", CODE_FAIL: "Code incorrect", CHARGEMENT_PARTIEL: "Chargement partiel",
  TENTATIVE_ECHOUEE: "Validation refusée (tentative)", SORTIE_REGULARISEE: "Sortie régularisée", ERREUR_DRIVE: "Photo : Drive indisponible",
};

/** Journal complet des événements de la livraison (replié par défaut). */
function Journal({ f }: { f: FriseData }) {
  const evts = f.evenements ?? [];
  if (!evts.length) return null;
  return (
    <details className="text-xs">
      <summary className="cursor-pointer text-slate-500 hover:text-slate-800">Journal détaillé ({evts.length} événements)</summary>
      <ol className="mt-2 space-y-1.5">
        {evts.map((e, i) => (
          <li key={i} className="flex gap-2 text-slate-600">
            <span className="num text-slate-400 shrink-0 w-28 whitespace-nowrap">{formatDateTime(e.at)}</span>
            <span>
              <span className="font-medium text-slate-800">{JALON_LABEL[e.jalon] ?? e.jalon}</span>
              {e.acteurNom && <> — {e.acteurNom}</>}
              {e.commentaire && <span className="text-slate-500"> · {e.commentaire}</span>}
            </span>
          </li>
        ))}
      </ol>
    </details>
  );
}

// ─── Livraisons : la frise de chaque livraison (coordinateur) ───────────────

type FiltreLivraison = "depassements" | "toutes" | "encours";

function Livraisons({
  email, depuis, recherche, site, zone, periode, ncParExp, onOuvrirNc,
}: {
  email: string; depuis: string; recherche: string; site: string; zone: string; periode: Periode;
  ncParExp: Map<string, NonConformite[]>; onOuvrirNc: (id: string) => void;
}) {
  const [filtre, setFiltre] = useState<FiltreLivraison>("depassements");
  const [ouverte, setOuverte] = useState<string | null>(null);
  const q = useQuery({
    queryKey: ["frises", email, depuis],
    queryFn: () => api.nonConformites.frises(email, depuis),
    enabled: !!email,
    refetchInterval: 60_000,
  });
  const toutes = useMemo(() => q.data?.liste ?? [], [q.data]);
  const base = useMemo(
    () =>
      toutes.filter((f) => {
        if (site && f.site !== site) return false;
        if (zone && !memeMagasin(f.zone, zone)) return false;
        if (f.jalons[0] && !dansPeriode(f.jalons[0].at, periode)) return false;
        if (recherche.trim()) {
          const r = recherche.trim();
          if (![f.numCmd, f.client, f.zone, f.plaque, f.chauffeur, f.numExpedition].some((c) => includesLower(c, r))) return false;
        }
        return true;
      }),
    [toutes, site, zone, periode, recherche],
  );
  const nDep = base.filter((f) => (f.totalMin ?? 0) > f.delaiMaxMin).length;
  const nCours = base.filter((f) => !f.termine).length;
  const liste = base.filter((f) =>
    filtre === "depassements" ? (f.totalMin ?? 0) > f.delaiMaxMin : filtre === "encours" ? !f.termine : true,
  );
  const choisie = ouverte ? toutes.find((f) => f.expId === ouverte) ?? null : null;

  return (
    <div className="space-y-3">
      <div className="rounded-lg border border-sky-200 bg-sky-50 px-3 py-2 text-xs text-sky-900 flex gap-2">
        <GanttChartSquare className="h-4 w-4 shrink-0 mt-0.5" />
        <span>
          Chaque livraison est décomposée en étapes : on voit combien de temps chacune a duré et qui l'a validée.
          Ouvrez une livraison pour enquêter, puis indiquez la vraie cause du retard si elle ne vient pas du magasin.
        </span>
      </div>
      <div className="flex flex-wrap gap-1.5">
        {([
          ["depassements", `Au-delà du seuil (${nDep})`],
          ["encours", `En cours (${nCours})`],
          ["toutes", `Toutes (${base.length})`],
        ] as [FiltreLivraison, string][]).map(([k, l]) => (
          <button
            key={k}
            onClick={() => setFiltre(k)}
            className={cn("px-3 py-1.5 rounded-full text-xs font-medium border transition-colors", filtre === k ? "bg-brand-900 text-white border-brand-900" : "bg-white text-slate-700 border-slate-200 hover:border-slate-300")}
          >
            {l}
          </button>
        ))}
      </div>

      {q.isLoading ? (
        <div className="card p-6 text-center text-sm text-slate-500">Chargement des livraisons…</div>
      ) : q.error ? (
        <div className="card p-6 border-red-200 bg-red-50 text-sm text-red-700">
          {q.error instanceof Error ? q.error.message : "Erreur"}
          <div className="text-xs mt-1">Si le message parle d'une action inconnue, la dernière version du script n'est pas encore déployée.</div>
        </div>
      ) : liste.length === 0 ? (
        <div className="card p-10 text-center text-sm text-slate-500">
          <CheckCircle2 className="h-8 w-8 mx-auto mb-2 text-emerald-500" />
          {filtre === "depassements" ? "Aucune livraison au-delà du seuil sur la période." : "Aucune livraison."}
        </div>
      ) : (
        <div className="space-y-2">
          {liste.map((f) => {
            const dep = (f.totalMin ?? 0) > f.delaiMaxMin;
            return (
              <button
                key={f.expId}
                onClick={() => setOuverte(f.expId)}
                className="card w-full text-left p-3 hover:border-brand-300 transition-colors grid gap-3 sm:grid-cols-[1fr_minmax(220px,300px)] items-center"
              >
                <div className="min-w-0">
                  <div className="flex flex-wrap items-center gap-1.5">
                    <span className="font-semibold text-slate-900 truncate">{f.numCmd || f.numExpedition || "Sans n°"}</span>
                    {f.client && <span className="text-sm text-slate-600 truncate">· {f.client}</span>}
                    {dep && <span className="badge-danger">+{formatDuree(f.depasseMin)}</span>}
                    {(f.ncs ?? []).map((n) => (
                      <span key={n.id} className={STATUT_BADGE[n.statut]}>{n.typeLabel}{n.imputation ? ` · ${IMPUTATION_COURT[n.imputation] ?? ""}` : ""}</span>
                    ))}
                  </div>
                  <div className="text-xs text-slate-500 mt-0.5">
                    {[f.zone, f.site].filter(Boolean).join(" — ")}
                    {f.jalons[0] && <> · {formatDateTime(f.jalons[0].at)}</>}
                    {f.plaque && <> · {f.plaque}</>}
                  </div>
                </div>
                <FriseMini f={f} />
              </button>
            );
          })}
        </div>
      )}

      {choisie && (
        <FicheLivraison
          f={choisie}
          email={email}
          ncs={ncParExp.get(choisie.expId) ?? []}
          onClose={() => setOuverte(null)}
          onOuvrirNc={(id) => { setOuverte(null); onOuvrirNc(id); }}
        />
      )}
    </div>
  );
}

function FicheLivraison({
  f, email, ncs, onClose, onOuvrirNc,
}: { f: FriseData; email: string; ncs: NonConformite[]; onClose: () => void; onOuvrirNc: (id: string) => void }) {
  const { data } = useQuery({
    queryKey: ["frise", f.expId, email],
    queryFn: () => api.nonConformites.frise(email, f.expId),
    refetchInterval: 60_000,
    retry: false,
  });
  const detail = data ?? f;
  return (
    <Modal
      open
      onClose={onClose}
      title={`Livraison ${f.numCmd || f.numExpedition || ""}`}
      description={[f.client, f.zone, f.site, f.plaque, f.chauffeur].filter(Boolean).join(" · ")}
      size="lg"
    >
      <div className="space-y-4">
        <FriseLivraison f={detail} />
        <Journal f={detail} />
        <div className="border-t border-line pt-3 space-y-2">
          <h3 className="text-sm font-semibold text-slate-900">Non-conformités liées</h3>
          {ncs.length === 0 ? (
            <p className="text-sm text-slate-500">Aucune non-conformité pour cette livraison.</p>
          ) : (
            ncs.map((n) => (
              <button key={n.id} onClick={() => onOuvrirNc(n.id)} className="w-full text-left rounded-lg border border-line p-2.5 hover:border-brand-300 flex items-center justify-between gap-2">
                <span className="text-sm text-slate-800">{n.typeLabel}{n.imputationLabel ? ` — cause : ${n.imputationLabel}` : ""}</span>
                <span className="flex items-center gap-2 shrink-0">
                  <span className={STATUT_BADGE[n.statut]}>{STATUT_LABEL[n.statut]}</span>
                  <ArrowRight className="h-4 w-4 text-slate-400" />
                </span>
              </button>
            ))
          )}
          <p className="text-xs text-slate-500">Ouvrez la non-conformité pour indiquer la cause du retard et saisir le justificatif.</p>
        </div>
      </div>
    </Modal>
  );
}

function Info({ label, valeur }: { label: string; valeur: string }) {
  return (
    <div className="min-w-0">
      <dt className="text-xs text-slate-500">{label}</dt>
      <dd className="text-slate-900 break-words">{valeur}</dd>
    </div>
  );
}

function ChoixDecision(props: { actif: boolean; onClick: () => void; icone: React.ReactNode; titre: string; sous: string; couleur: "emerald" | "amber" | "red" }) {
  const actifCls = { emerald: "border-emerald-500 bg-emerald-50", amber: "border-amber-500 bg-amber-50", red: "border-red-500 bg-red-50" }[props.couleur];
  return (
    <button
      type="button"
      onClick={props.onClick}
      className={cn("text-left rounded-lg border p-3 transition-colors", props.actif ? actifCls : "border-line bg-white hover:border-slate-300")}
    >
      <div className="flex items-center gap-1.5 text-sm font-semibold text-slate-900">{props.icone}{props.titre}</div>
      <div className="text-xs text-slate-500 mt-0.5">{props.sous}</div>
    </button>
  );
}

// ─── Nouveau constat ─────────────────────────────────────────────────────────

function NouveauConstat({ onClose }: { onClose: () => void }) {
  const { user } = useAuth();
  const toast = useToast();
  const qc = useQueryClient();
  const sitesDispo = user?.site && user.role === "coordinateur" ? [user.site] : ["Dakar", "Diamniadio"];
  const [site, setSite] = useState(sitesDispo[0]);
  const [zone, setZone] = useState("");
  const [numCmd, setNumCmd] = useState("");
  const [client, setClient] = useState("");
  const [detail, setDetail] = useState("");
  const [photo, setPhoto] = useState<string | null>(null);

  const magasins = MAGASINS.filter((m) => m.site === site);

  const m = useMutation({
    mutationFn: () =>
      api.nonConformites.creer({
        acteurEmail: user?.email ?? "", detail: detail.trim(), site, zone: zone || undefined,
        numCmd: numCmd.trim() || undefined, client: client.trim() || undefined, photo: photo || undefined,
      }),
    onSuccess: () => {
      toast.success("Constat enregistré — le responsable est prévenu");
      qc.invalidateQueries({ queryKey: ["non-conformites"] });
      onClose();
    },
    onError: (e) => toast.error(e instanceof Error ? e.message : "Erreur"),
  });

  function envoyer(e: FormEvent) {
    e.preventDefault();
    if (detail.trim().length < 5) return toast.error("Décris le constat.");
    if (!zone) return toast.error("Choisis le magasin concerné.");
    m.mutate();
  }

  return (
    <Modal
      open
      onClose={onClose}
      title="Nouveau constat"
      description="Anomalie relevée lors d'une visite : le responsable du magasin devra l'expliquer sous 24 h."
      footer={
        <>
          <button className="btn-outline" onClick={onClose} disabled={m.isPending}>Annuler</button>
          <button className="btn-primary" form="form-constat" disabled={m.isPending}>{m.isPending ? "Envoi…" : "Enregistrer"}</button>
        </>
      }
    >
      <form id="form-constat" onSubmit={envoyer} className="space-y-3">
        <div className="grid grid-cols-2 gap-2">
          <div>
            <label className="label">Site *</label>
            <select className="input" value={site} onChange={(e) => { setSite(e.target.value); setZone(""); }}>
              {sitesDispo.map((s) => <option key={s}>{s}</option>)}
            </select>
          </div>
          <div>
            <label className="label">Magasin *</label>
            <select className="input" value={zone} onChange={(e) => setZone(e.target.value)}>
              <option value="">Choisir…</option>
              {magasins.map((mg) => <option key={mg.id} value={mg.label}>{mg.label}</option>)}
            </select>
          </div>
          <div>
            <label className="label">N° commande</label>
            <input className="input" value={numCmd} onChange={(e) => setNumCmd(e.target.value)} placeholder="Facultatif" />
          </div>
          <div>
            <label className="label">Client</label>
            <input className="input" value={client} onChange={(e) => setClient(e.target.value)} placeholder="Facultatif" />
          </div>
        </div>
        <div>
          <label className="label">Constat *</label>
          <textarea className="input min-h-[90px]" value={detail} onChange={(e) => setDetail(e.target.value)} placeholder="Ce que tu as observé, précisément" />
        </div>
        <PhotoCapture label="Photo (facultatif)" value={photo} onChange={setPhoto} maxDimension={1280} quality={0.8} />
      </form>
    </Modal>
  );
}

// ─── Suivi chiffré ───────────────────────────────────────────────────────────

function Barres({ titre, lignes }: { titre: string; lignes: { label: string; n: number }[] }) {
  const max = Math.max(1, ...lignes.map((l) => l.n));
  return (
    <div className="card p-4">
      <h3 className="text-sm font-semibold text-slate-900 mb-3">{titre}</h3>
      {lignes.length === 0 ? (
        <p className="text-sm text-slate-400">Aucune donnée.</p>
      ) : (
        <ul className="space-y-2">
          {lignes.map((l) => (
            <li key={l.label}>
              <div className="flex justify-between text-xs text-slate-600 mb-0.5">
                <span className="truncate pr-2">{l.label}</span>
                <span className="num font-medium text-slate-900">{l.n}</span>
              </div>
              <div className="h-1.5 rounded-full bg-slate-100">
                <div className="h-full rounded-full bg-brand-900" style={{ width: `${(l.n / max) * 100}%` }} />
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

function compter(items: string[]): { label: string; n: number }[] {
  const m = new Map<string, number>();
  items.filter(Boolean).forEach((k) => m.set(k, (m.get(k) ?? 0) + 1));
  return [...m.entries()].map(([label, n]) => ({ label, n })).sort((a, b) => b.n - a.n);
}

function Suivi({ liste: toutes, periode }: { liste: NonConformite[]; periode: Periode }) {
  // Les non-conformités annulées (ancien calcul de durée corrigé) ne comptent pas dans les chiffres
  const liste = useMemo(() => toutes.filter((n) => n.decision !== "annulee"), [toutes]);
  const stats = useMemo(() => {
    const total = liste.length;
    const cloturees = liste.filter((n) => n.statut === "cloturee");
    const confirmees = liste.filter((n) => n.decision === "confirmee").length;
    const acceptees = liste.filter((n) => n.decision === "acceptee").length;
    const delais = cloturees
      .filter((n) => n.clotureLe)
      .map((n) => (new Date(n.clotureLe as string).getTime() - new Date(n.creeLe).getTime()) / 3600000);
    const delaiMoyen = delais.length ? Math.round(delais.reduce((a, b) => a + b, 0) / delais.length) : null;
    const parResp = compter(liste.flatMap((n) => n.responsableEmail.split(",").map((s) => s.trim())));
    const motifs = compter(liste.flatMap((n) => (n.motifs ? n.motifs.split(",").map((s) => s.trim()) : [])));
    return {
      total, confirmees, acceptees, delaiMoyen,
      ouvertes: liste.filter((n) => n.statut !== "cloturee").length,
      sansExplication: liste.filter((n) => n.enRetardJustif).length,
      actionsRetard: liste.filter((n) => n.enRetardAction).length,
      parType: compter(liste.map((n) => n.typeLabel)),
      parSite: compter(liste.map((n) => [n.site, n.zone].filter(Boolean).join(" — "))),
      parResp: parResp.slice(0, 8),
      recidivistes: parResp.filter((r) => r.n >= 3),
      motifs: motifs.slice(0, 8),
    };
  }, [liste]);

  return (
    <div className="space-y-4">
      <p className="text-xs text-slate-500">
        Non-conformités ouvertes dans la période
        {periode.debut ? ` du ${periode.debut}` : ""}{periode.fin ? ` au ${periode.fin}` : ""} (filtres actifs appliqués).
      </p>
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        <Kpi titre="Total" valeur={stats.total} />
        <Kpi titre="Ouvertes" valeur={stats.ouvertes} />
        <Kpi titre="Sans explication > 24 h" valeur={stats.sansExplication} alerte={stats.sansExplication > 0} />
        <Kpi titre="Actions en retard" valeur={stats.actionsRetard} alerte={stats.actionsRetard > 0} />
        <Kpi titre="Confirmées" valeur={stats.confirmees} />
        <Kpi titre="Explications acceptées" valeur={stats.acceptees} />
        <Kpi titre="Délai moyen de clôture" valeur={stats.delaiMoyen === null ? "—" : stats.delaiMoyen < 48 ? `${stats.delaiMoyen} h` : `${Math.round(stats.delaiMoyen / 24)} j`} />
        <Kpi titre="Responsables à 3+ NC" valeur={stats.recidivistes.length} alerte={stats.recidivistes.length > 0} />
      </div>
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-3">
        <Barres titre="Par type" lignes={stats.parType} />
        <Barres titre="Par magasin" lignes={stats.parSite} />
        <Barres titre="Par responsable" lignes={stats.parResp} />
        <Barres titre="Motifs de retard les plus cités" lignes={stats.motifs} />
      </div>
    </div>
  );
}

function Kpi({ titre, valeur, alerte }: { titre: string; valeur: number | string; alerte?: boolean }) {
  return (
    <div className="card p-3">
      <div className="text-xs text-slate-500">{titre}</div>
      <div className={cn("num text-2xl font-semibold", alerte ? "text-red-600" : "text-slate-900")}>{valeur}</div>
    </div>
  );
}
